{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js"
  }
}
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { randomUUID } from 'node:crypto';
import { DatabaseSync } from 'node:sqlite';

const root = dirname(fileURLToPath(import.meta.url));
const dbPath = resolve(process.env.DB_PATH || join(root, 'data', 'workboard.sqlite'));
const { mkdir } = await import('node:fs/promises');
await mkdir(dirname(dbPath), { recursive: true });
const db = new DatabaseSync(dbPath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  created_at INTEGER NOT NULL
)`);
db.exec(`CREATE TABLE IF NOT EXISTS tasks (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0,
  created_at INTEGER NOT NULL
)`);

const send = (res, status, body, type = 'application/json; charset=utf-8') => {
  res.writeHead(status, { 'Content-Type': type, 'Cache-Control': 'no-store' });
  res.end(typeof body === 'string' ? body : JSON.stringify(body));
};

const server = createServer(async (req, res) => {
  const url = new URL(req.url, 'http://localhost');
  if (req.method === 'GET' && url.pathname === '/health') {
    return send(res, 200, { status: 'ok' });
  }
  if (req.method === 'GET' && url.pathname === '/api/projects') {
    return send(res, 200, db.prepare('SELECT id, name FROM projects ORDER BY created_at, rowid').all());
  }
  if (req.method === 'POST' && url.pathname === '/api/projects') {
    let body = '';
    for await (const chunk of req) body += chunk;
    let name;
    try { name = JSON.parse(body).name; } catch { return send(res, 400, { error: 'Invalid request' }); }
    name = typeof name === 'string' ? name.trim() : '';
    if (!name) return send(res, 400, { error: 'Project name is required' });
    const project = { id: randomUUID(), name };
    db.prepare('INSERT INTO projects (id, name, created_at) VALUES (?, ?, ?)').run(project.id, project.name, Date.now());
    return send(res, 201, project);
  }
  const projectTasks = url.pathname.match(/^\/api\/projects\/([^/]+)\/tasks$/);
  if (projectTasks) {
    let projectId;
    try { projectId = decodeURIComponent(projectTasks[1]); } catch { return send(res, 400, { error: 'Invalid project id' }); }
    if (!db.prepare('SELECT 1 FROM projects WHERE id = ?').get(projectId)) return send(res, 404, { error: 'Project not found' });
    if (req.method === 'GET') {
      return send(res, 200, db.prepare('SELECT id, project_id AS projectId, title, completed FROM tasks WHERE project_id = ? ORDER BY created_at, rowid').all(projectId));
    }
    if (req.method === 'POST') {
      let body = '';
      for await (const chunk of req) body += chunk;
      let title;
      try { title = JSON.parse(body).title; } catch { return send(res, 400, { error: 'Invalid request' }); }
      title = typeof title === 'string' ? title.trim() : '';
      if (!title) return send(res, 400, { error: 'Task title is required' });
      const task = { id: randomUUID(), projectId, title, completed: 0 };
      db.prepare('INSERT INTO tasks (id, project_id, title, completed, created_at) VALUES (?, ?, ?, 0, ?)').run(task.id, projectId, title, Date.now());
      return send(res, 201, task);
    }
  }
  const taskCompletion = url.pathname.match(/^\/api\/projects\/([^/]+)\/tasks\/([^/]+)$/);
  if (req.method === 'PATCH' && taskCompletion) {
    let projectId, taskId;
    try { projectId = decodeURIComponent(taskCompletion[1]); taskId = decodeURIComponent(taskCompletion[2]); } catch { return send(res, 400, { error: 'Invalid task id' }); }
    let body = '';
    for await (const chunk of req) body += chunk;
    let completed;
    try { completed = JSON.parse(body).completed; } catch { return send(res, 400, { error: 'Invalid request' }); }
    if (typeof completed !== 'boolean') return send(res, 400, { error: 'Invalid completion state' });
    const result = db.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?').run(completed ? 1 : 0, taskId, projectId);
    if (!result.changes) return send(res, 404, { error: 'Task not found' });
    return send(res, 200, { id: taskId, projectId, completed: completed ? 1 : 0 });
  }
  if (req.method === 'GET' && url.pathname === '/') {
    try { return send(res, 200, await readFile(join(root, 'public', 'index.html'), 'utf8'), 'text/html; charset=utf-8'); }
    catch { return send(res, 500, 'Application page unavailable', 'text/plain; charset=utf-8'); }
  }
  if (req.method === 'GET' && /^\/projects\/[^/]+$/.test(url.pathname)) {
    return send(res, 200, await readFile(join(root, 'public', 'index.html'), 'utf8'), 'text/html; charset=utf-8');
  }
  return send(res, 404, { error: 'Not found' });
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0');
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Workboard</title>
  <style>
    :root { color-scheme: light; font-family: system-ui, sans-serif; color: #17212b; background: #f5f7fa; }
    body { margin: 0; }
    main { max-width: 760px; margin: 56px auto; padding: 0 24px; }
    h1 { font-size: 2rem; margin: 0 0 28px; }
    form, .project-row { background: white; border: 1px solid #dce2e8; border-radius: 10px; padding: 20px; }
    label { display: block; font-weight: 600; margin-bottom: 8px; }
    input { box-sizing: border-box; width: 100%; padding: 11px 12px; border: 1px solid #aeb9c4; border-radius: 6px; font: inherit; }
    button { border: 0; border-radius: 6px; padding: 10px 16px; background: #245bc5; color: white; font: inherit; font-weight: 600; cursor: pointer; }
    form button { margin-top: 12px; }
    button:focus-visible, input:focus-visible { outline: 3px solid #91b8ff; outline-offset: 2px; }
    #alert { color: #a22323; margin: 12px 0 0; }
    #projects { display: grid; gap: 10px; margin-top: 24px; }
    .project-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; }
    .project-name { overflow-wrap: anywhere; }
    .task-form, .task-filter { margin-top: 18px; }
    #tasks { display: grid; gap: 10px; margin-top: 18px; }
    .task-row { display: flex; align-items: center; gap: 12px; background: white; border: 1px solid #dce2e8; border-radius: 10px; padding: 16px 20px; }
    .task-row input { width: auto; }
  </style>
</head>
<body>
  <main id="app"></main>
  <script>
    const app = document.querySelector('#app');
    const escapeHtml = value => String(value).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
    async function render() {
      const match = location.pathname.match(/^\/projects\/([^/]+)$/);
      if (match) {
        let project;
        try {
          const response = await fetch('/api/projects');
          project = (await response.json()).find(item => item.id === decodeURIComponent(match[1]));
        } catch {}
        if (!project) { history.replaceState({}, '', '/'); return render(); }
        app.innerHTML = `<button id="back" type="button">Projects</button><h1>${escapeHtml(project.name)}</h1>
          <form class="task-form" id="task-form" novalidate>
            <label for="task-title">Task title</label>
            <input id="task-title" name="title" type="text" autocomplete="off">
            <button type="submit">Create task</button>
            <p id="alert" role="alert" hidden></p>
          </form>
          <div class="task-filter"><label for="task-filter">Task filter</label>
            <select id="task-filter"><option>All</option><option>Open</option><option>Completed</option></select>
          </div>
          <section id="tasks" aria-label="Tasks"></section>`;
        document.querySelector('#back').addEventListener('click', () => { history.pushState({}, '', '/'); render(); });
        const tasks = document.querySelector('#tasks');
        const filter = document.querySelector('#task-filter');
        async function refreshTasks() {
          const response = await fetch(`/api/projects/${encodeURIComponent(project.id)}/tasks`);
          const allTasks = await response.json();
          const visible = allTasks.filter(task => filter.value === 'All' || (filter.value === 'Open' ? !task.completed : !!task.completed));
          tasks.innerHTML = visible.map(task => `<div class="task-row" data-testid="task-row"><input type="checkbox" data-id="${escapeHtml(task.id)}" aria-label="Complete ${escapeHtml(task.title)}" ${task.completed ? 'checked' : ''}><span>${escapeHtml(task.title)}</span></div>`).join('');
          tasks.querySelectorAll('input[type="checkbox"]').forEach(checkbox => checkbox.addEventListener('change', async () => {
            await fetch(`/api/projects/${encodeURIComponent(project.id)}/tasks/${encodeURIComponent(checkbox.dataset.id)}`, { method: 'PATCH', headers: {'Content-Type':'application/json'}, body: JSON.stringify({ completed: checkbox.checked }) });
            await refreshTasks();
          }));
        }
        filter.addEventListener('change', refreshTasks);
        document.querySelector('#task-form').addEventListener('submit', async event => {
          event.preventDefault();
          const input = document.querySelector('#task-title');
          const alert = document.querySelector('#alert');
          const title = input.value.trim();
          if (!title) { alert.textContent = 'Task title is required'; alert.hidden = false; input.focus(); return; }
          alert.hidden = true;
          const response = await fetch(`/api/projects/${encodeURIComponent(project.id)}/tasks`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify({ title }) });
          if (response.ok) { input.value = ''; await refreshTasks(); }
        });
        await refreshTasks();
        return;
      }
      app.innerHTML = `<h1>Workboard</h1>
        <form id="create-form" novalidate>
          <label for="project-name">Project name</label>
          <input id="project-name" name="name" type="text" autocomplete="off">
          <button type="submit">Create project</button>
          <p id="alert" role="alert" hidden></p>
        </form>
        <section id="projects" aria-label="Projects"></section>`;
      const list = document.querySelector('#projects');
      async function refresh() {
        const response = await fetch('/api/projects');
        const projects = await response.json();
        list.innerHTML = projects.map(project => `<div class="project-row" data-testid="project-row"><span class="project-name">${escapeHtml(project.name)}</span><button type="button" data-id="${escapeHtml(project.id)}">Open project</button></div>`).join('');
        list.querySelectorAll('button').forEach(button => button.addEventListener('click', () => {
          history.pushState({}, '', `/projects/${encodeURIComponent(button.dataset.id)}`); render();
        }));
      }
      document.querySelector('#create-form').addEventListener('submit', async event => {
        event.preventDefault();
        const input = document.querySelector('#project-name');
        const alert = document.querySelector('#alert');
        const name = input.value.trim();
        if (!name) { alert.textContent = 'Project name is required'; alert.hidden = false; input.focus(); return; }
        alert.hidden = true;
        const response = await fetch('/api/projects', { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify({ name }) });
        if (response.ok) { input.value = ''; await refresh(); }
      });
      await refresh();
    }
    addEventListener('popstate', render);
    render();
  </script>
</body>
</html>
